from collections import deque

def can_reach_2_through_1s(grid, i, j):
    """Check if (i,j) can reach a 2 via a path of 1s using 8-way connectivity"""
    q = deque([(i, j)])
    visited = set([(i, j)])

    while q:
        r, c = q.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr != 0 or dc != 0:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                        if (nr, nc) not in visited:
                            if grid[nr, nc] == 2:
                                return True
                            elif grid[nr, nc] == 1:
                                visited.add((nr, nc))
                                q.append((nr, nc))
    return False

